def components(g, color):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps={}
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=set()
                while stack:
                    a,b=stack.pop(); cells.add((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==color:
                            seen[na][nb]=True; stack.append((na,nb))
                comps[frozenset(cells)]=cells
    return comps
